/// <summary>
/// Base class for PricingAttribute table <c>EcoResProductVariantStyle</c>
/// </summary>
internal abstract class UPSPricingAttributeEcoResProductVariantStyle extends UPSAbstractPricingAttribute implements UPSIPricingAttribute
{
}

Method.Source:
protected EcoResProductVariantStyle getTableRecord(Common _pricingObject)
{
    EcoResProductVariantStyle   ecoResProductVariantStyle;
    RefRecId                    productDimensionAttribute;
    SalesLine                   salesLine = _pricingObject as SalesLine;

    if (salesLine)
    {
        productDimensionAttribute = EcoResProductDimensionAttribute::inventDimFieldId2DimensionAttributeRecId(fieldNum(InventDim, InventStyleId));
        ecoResProductVariantStyle = EcoResProductVariantStyle::find(salesLine.inventTable().Product, productDimensionAttribute);
    }

    return ecoResProductVariantStyle;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbdsRoot, qbdsEcoResProduct;

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(InventTable));
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(tableStr(EcoResDistinctProductVariant)))
    {
        qbdsEcoResProduct = _qbdsMap.lookup(tableStr(EcoResDistinctProductVariant));
    }
    else
    {
        qbdsEcoResProduct = qbdsRoot.addDataSource(tableStr(EcoResDistinctProductVariant));
        qbdsEcoResProduct.joinMode(JoinMode::ExistsJoin);
        qbdsEcoResProduct.addLink(fieldNum(InventTable, Product), fieldNum(EcoResDistinctProductVariant, ProductMaster));
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(EcoResDistinctProductVariant), qbdsEcoResProduct);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        RefRecId productDimensionAttribute = EcoResProductDimensionAttribute::inventDimFieldId2DimensionAttributeRecId(fieldNum(InventDim, InventStyleId));

        qbds = qbdsEcoResProduct.addDataSource(tableNum(EcoResProductVariantStyle));
        qbds.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantStyle, DistinctProductVariant));
        qbds.joinMode(JoinMode::ExistsJoin);

        qbds.addRange(fieldNum(EcoResProductVariantStyle, ProductDimensionAttribute)).value(queryValue(productDimensionAttribute));

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
